    """Embed texts; returns an L2-normalized float32 array of shape (len(texts), 1536)."""
    model = model or model_name("EMBEDDING_MODEL")
    keys = [hashlib.sha256(f"{model}\n{t}".encode()).hexdigest() for t in texts]
    vectors = {}
